+                Arrays.fill(AFTER, SENTINEL);
+                testEmptyTwoPredJoin(outer, small);
+                for (int i = 0; i < A.length; i++) {
+                    int expected = SENTINEL;
+                    if (outer) {
+                        expected = small ? (i < SMALL.length ? B[i] : SENTINEL) : A[i];
+                    }
+                    Asserts.assertEQ(BEFORE[i], A[i]);
