+    @DontInline
+    @ForceCompile(CompLevel.C2)
+    public static void clobber() {
+        calls++;
+        ByteVector.fromArray(ByteVector.SPECIES_128, BYTES, 0).add((byte) 3).intoArray(BYTE_RESULT, 0);
+        for (int i = 0; i < B.length; i++) {
+            LEFT[i] = B[i] + calls;
+        }
+    }
